import{c as r,Q as d,j as o,m as n}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"面向对象基础","description":"","frontmatter":{"title":"面向对象基础"},"headers":[],"relativePath":"综合知识/面向对象/面向对象基础.md","filePath":"综合知识/面向对象/面向对象基础.md","lastUpdated":null}'),a={name:"综合知识/面向对象/面向对象基础.md"};function e(s,t,g,l,h,i){return d(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="面向对象基本概念" tabindex="-1">面向对象基本概念 <a class="header-anchor" href="#面向对象基本概念" aria-label="Permalink to &quot;面向对象基本概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>说明</th><th>关键记忆</th></tr></thead><tbody><tr><td><strong>对象</strong></td><td>由数据及其操作构成的封装体，是构成系统的基本单位</td><td>对象 = 对象名 + 属性 + 方法</td></tr><tr><td><strong>类</strong></td><td>实体的形式化描述，属性和操作封装在一起</td><td>类是对象的模板，对象是类的实例</td></tr><tr><td><strong>抽象</strong></td><td>通过特定实例抽取共同特征形成概念</td><td>强调主要特征，忽略次要特征</td></tr><tr><td><strong>封装</strong></td><td>信息隐蔽技术，将数据和操作封装成整体</td><td>对数据访问只能通过对外接口进行</td></tr><tr><td><strong>继承</strong></td><td>类之间的层次关系（父子）</td><td>单继承/多继承，子类复用父类特征</td></tr><tr><td><strong>多态</strong></td><td>不同对象收到同一消息产生不同结果</td><td>由继承机制支持，通用消息放抽象层</td></tr><tr><td><strong>接口</strong></td><td>描述操作规范说明</td><td>只说明做什么，不定义如何做</td></tr><tr><td><strong>消息</strong></td><td>对象间交互，向目标对象发送操作请求</td><td>—</td></tr><tr><td><strong>覆盖（Override）</strong></td><td>子类重定义与父类<strong>同名同参</strong>的方法</td><td>子类用自己的实现置换父类实现</td></tr><tr><td><strong>函数重载（Overload）</strong></td><td>与子类父类无关，<strong>同名不同参数</strong></td><td>参数类型/个数/顺序不同</td></tr><tr><td><strong>绑定</strong></td><td>过程调用和响应代码的结合过程</td><td>静态绑定（编译时）/ 动态绑定（运行时）</td></tr></tbody></table><blockquote><p>覆盖 vs 重载：<strong>覆盖 = 子类重写父类同名同参方法；重载 = 同类同名不同参，与父子无关。</strong></p></blockquote><h4 id="类的三种类型" tabindex="-1">类的三种类型 <a class="header-anchor" href="#类的三种类型" aria-label="Permalink to &quot;类的三种类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>实体类</strong></td><td>表示现实世界真实实体</td><td>人、物、客户</td></tr><tr><td><strong>接口类（边界类）</strong></td><td>提供用户与系统交互方式</td><td>窗口、对话框、二维码（人接口）；数据收发的系统接口</td></tr><tr><td><strong>控制类</strong></td><td>控制活动流，充当协调者</td><td>业务逻辑控制器</td></tr></tbody></table><hr><h4 id="多态的四种类型" tabindex="-1">多态的四种类型 <a class="header-anchor" href="#多态的四种类型" aria-label="Permalink to &quot;多态的四种类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>参数多态</strong></td><td>不同类型参数多种结构类型（泛型）</td></tr><tr><td><strong>包含多态</strong></td><td>父子类型关系（子类型多态）</td></tr><tr><td><strong>过载多态</strong></td><td>一个名字不同含义（重载）</td></tr><tr><td><strong>强制多态</strong></td><td>强制类型转换</td></tr></tbody></table><h3 id="面向对象的分析" tabindex="-1">面向对象的分析 <a class="header-anchor" href="#面向对象的分析" aria-label="Permalink to &quot;面向对象的分析&quot;">​</a></h3><p>面向对象的分析：是为了确定问题域，理解问题。包含五个活动：认定对象、组织对象、描述对象间的相互作用、确定对象的操作、定义对象的内部信息。</p><hr><p><strong>OOA（面向对象分析）</strong>：确认问题域，理解问题。分析模型 = 顶层架构图 + 用例与用例图 + <strong>领域概念模型</strong>。</p><h3 id="面向对象需求建模" tabindex="-1">面向对象需求建模 <a class="header-anchor" href="#面向对象需求建模" aria-label="Permalink to &quot;面向对象需求建模&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517230922.png" alt="image.png"></p><h3 id="面向对象的设计" tabindex="-1">面向对象的设计 <a class="header-anchor" href="#面向对象的设计" aria-label="Permalink to &quot;面向对象的设计&quot;">​</a></h3><p><strong>OOD（面向对象设计）</strong>：设计模型包含 → 以<strong>包图</strong>表示的软件体系结构图、以交互图表示的用例实现图、完整精确的类图、描述复杂对象的<strong>状态图</strong>、描述流程化处理的<strong>活动图</strong>。</p><hr><h4 id="面向对象设计原则" tabindex="-1">面向对象设计原则 <a class="header-anchor" href="#面向对象设计原则" aria-label="Permalink to &quot;面向对象设计原则&quot;">​</a></h4><blockquote><p>面向对象设计五大原则。</p></blockquote><p>SOLID 设计原则</p><table tabindex="0"><thead><tr><th>原则</th><th>说明</th><th>口诀</th></tr></thead><tbody><tr><td><strong>单一职责原则（SRP）</strong></td><td>一个类只负责一个功能领域中的相应职责</td><td>一类一事</td></tr><tr><td><strong>开闭原则（OCP）</strong></td><td>对扩展开放，对修改关闭</td><td>加功能不修代码</td></tr><tr><td><strong>里氏替换原则（LSP）</strong></td><td>子类可以替换父类出现，且不影响程序正确性</td><td>子代父职</td></tr><tr><td><strong>接口隔离原则（ISP）</strong></td><td>使用多个专门的接口比使用单一的总接口好</td><td>接口要专一</td></tr><tr><td><strong>依赖倒置原则（DIP）</strong></td><td>抽象不应依赖细节，细节应依赖抽象；<strong>针对接口编程，不针对实现编程</strong></td><td>依赖抽象不依赖具体</td></tr></tbody></table><blockquote><p>其他原则：<strong>最少知识原则（迪米特法则）</strong> — 一个对象应对其他对象有尽可能少的了解。<strong>合成复用原则</strong> — 优先使用对象组合而非继承。</p></blockquote><p>上述(1)(5)是面向对象方法中的五大原则。除了这五大原则之外，Robert C.Martin提出的面向对象设计原则还包括以下几个。</p><ul><li>(6)重用发布等价原则。重用的粒度就是发布的粒度。</li><li>(7)共同封闭原则。包中的所有类对于同一类性质的变化应该是共同封闭的。一个变化若对一个包产生影响，则将对该包中的所有类产生影响，而对于其他的包不造成任何影响。</li><li>(8)共同重用原则。一个包中的所有类应该是共同重用的。如果重用了包中的一个类，那么就要重用包中的所有类。</li><li>(9)无环依赖原则。在包的依赖关系图中不允许存在环，即包之间的结构必须是一个直接的五环图形。</li><li>(10)稳定依赖原则。朝着稳定的方向进行依赖。</li><li>(11)稳定抽象原则。包的抽象程度应该和其稳定程度一致。</li></ul><h3 id="面向对象的测试" tabindex="-1">面向对象的测试 <a class="header-anchor" href="#面向对象的测试" aria-label="Permalink to &quot;面向对象的测试&quot;">​</a></h3><p><strong>OOT（面向对象测试）四层级：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">层级</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>算法层</strong></td><td>测试单个操作/方法</td></tr><tr><td style="text-align:center;"><strong>类层</strong></td><td>测试单个类的所有操作</td></tr><tr><td style="text-align:center;"><strong>模板层</strong></td><td>测试一组协同工作的类（模板/组件）</td></tr><tr><td style="text-align:center;"><strong>系统层</strong></td><td>测试整个系统</td></tr></tbody></table>',27)])])}const p=r(a,[["render",e]]);export{c as __pageData,p as default};
